from fractions import Fraction as F
f={'I':F(85,100)*F(80,100),'II':F(75,100)*F(90,100),'III':F(67,100)}
best=min(f,key=f.get)
opts={'A':'II','B':'I or II','C':'III','D':'I'}
assert best==opts['C'] and list(f.values()).count(f[best])==1
for k in 'ABD': assert best!=opts[k]

