v=res.pop()
opts={'A':4,'B':3,'C':1,'D':2}
assert v==opts['D']
for k in 'ABC': assert v!=opts[k]

m={'A':'Q','B':'P','C':'R'}
inv={v:k for k,v in m.items()}
ang={'A':180-65-75,'B':65,'C':75}
side={frozenset('AB'):7,frozenset('AC'):8}
def S(p,q):  # side of QPR mapped back
    return side.get(frozenset(inv[p]+inv[q]))
def A(p): return ang[inv[p]]
res={
 'A': S('P','R')==8 and A('P')==65,
 'B': S('P','Q')==7 and A('R')==75,
 'C': A('Q')==40 and S('R','Q')==7,
 'D': A('R')==75 and S('P','Q')==8,
}
assert [k for k,v in res.items() if v]==['B']

import sympy as sp
A=sp.symbols('A',real=True)
sols=[s for s in sp.solve(3*sp.sin(A)+4*sp.cos(A)-5,A)]
ts={sp.nsimplify(sp.simplify(sp.tan(s))) for s in sols}
assert ts=={sp.Rational(3,4)}
t=ts.pop()
opts={'A':sp.Rational(5,4),'B':sp.Rational(3,4),'C':sp.Rational(3,5),'D':sp.Rational(4,5)}
assert t==opts['B']
for k in 'ACD': assert t!=opts[k]
